                    "sql": "CREATE OR REPLACE TABLE `MapleMonk.STPL_pandl_intermediate` as WITH daily_store_costs AS ( SELECT date_generated AS cost_date, UPPER(store) AS store, lower(type) AS cost_type, CASE WHEN lower(Commission_Type) LIKE \'%percent%\' THEN CAST(REPLACE(REPLACE(Actual_Value, \'%\', \'\'),\",\",\"\") AS FLOAT64) / 100 * 0.15 ELSE NULL END AS commission_percent, CASE WHEN lower(Commission_Type) NOT LIKE \'%percent%\' THEN CAST(REPLACE(REPLACE(Actual_Value, \'%\', \'\'),\",\",\"\") AS FLOAT64) * 0.15 / (DATE_DIFF( PARSE_DATE(\'%e-%b-%y\', END_DATE), PARSE_DATE(\'%e-%b-%y\', START_DATE), DAY ) + 1) ELSE NULL END AS daily_fixed_value FROM MapleMonk.STPL_bnb_Offline_Cost, UNNEST(GENERATE_DATE_ARRAY( PARSE_DATE(\'%e-%b-%y\', START_DATE), PARSE_DATE(\'%e-%b-%y\', END_DATE) )) AS date_generated WHERE lower(type) != \'exhibition\' ), daily_exhibition_costs AS ( SELECT date_generated AS cost_date, UPPER(store) AS store, CASE WHEN lower(Commission_Type) LIKE \'%percent%\' THEN CAST(REPLACE(Actual_Value, \'%\', \'\') AS FLOAT64) / 100 ELSE NULL END AS commission_percent, CASE WHEN lower(Commission_Type) NOT LIKE \'%percent%\' THEN CAST(REPLACE(Actual_Value, \'%\', \'\') AS FLOAT64) / (DATE_DIFF( PARSE_DATE(\'%e-%b-%y\', END_DATE), PARSE_DATE(\'%e-%b-%y\', START_DATE), DAY ) + 1) ELSE NULL END AS daily_fixed_value FROM `MapleMonk.STPL_bnb_Offline_Cost`, UNNEST(GENERATE_DATE_ARRAY( PARSE_DATE(\'%e-%b-%y\', START_DATE), PARSE_DATE(\'%e-%b-%y\', END_DATE) )) AS date_generated WHERE lower(type) = \'exhibition\' ), cte as ( select coalesce(ORDER_DATE,marketing_nocategory_date,marketing_date,store_rent.cost_date, store_cam.cost_date, store_elec.cost_date, store_int.cost_date, store_hvac.cost_date, store_other.cost_date, store_salary.cost_date, store_incentive.cost_date, store_bank.cost_date) as Date_pre ,CASE when coalesce(store_rent.store,store_cam.store,store_elec.store,store_int.store,store_hvac.store, store_other.store,store_salary.sTORE,store_incentive.store,store_bank.store) is not null then \'SHOPIFY POS\' else sc.MARKETPLACE end as MARKETPLACE_pre ,COALESCE( FINAL_MARKETPLACE, CASE WHEN LOWER(COALESCE(msc.marketing_channel, mscc.marketing_nocategory_channel)) LIKE \'%amazon%\' THEN \'AMAZON\' WHEN LOWER(COALESCE(msc.marketing_channel, mscc.marketing_nocategory_channel)) like any (\'facebook\',\'google\') THEN \'WEBSITE\' when coalesce(store_rent.store,store_cam.store,store_elec.store,store_int.store,store_hvac.store, store_other.store,store_salary.sTORE,store_incentive.store,store_bank.store) is not null then \'EBO\' ELSE LOWER(COALESCE(msc.marketing_channel, mscc.marketing_nocategory_channel)) END ) AS FINAL_MARKETPLACE_pre ,coalesce(CHANNEL,msc.marketing_channel,mscc.marketing_nocategory_channel) channel_pre ,upper(coalesce(SOURCE,store_rent.store,store_cam.store,store_elec.store,store_int.store,store_hvac.store,store_other.store ,store_salary.sTORE,store_incentive.store,store_bank.store)) as SOURCE ,REFERENCE_CODE ,Order_id ,CASE WHEN coalesce(store_rent.store,store_cam.store,store_elec.store,store_int.store,store_hvac.store, store_other.store,store_salary.sTORE,store_incentive.store,store_bank.store) is not null then \'OFFLINE\' ELSE sc.Marketplace_Segment end as marketplace_segment_pre ,new_customer_flag ,customer_id_final ,CASE WHEN lower(coalesce(sc.Brand,fsm.brand)) LIKE \'%everpret%\' THEN \'EVERPRET\' WHEN lower(coalesce(sc.Brand,fsm.brand)) LIKE \'%doto%\' THEN \'DOTO\' ELSE lower(coalesce(sc.Brand,fsm.brand)) END as Brand_Pre ,SKU ,sc.COMMONSKU ,upper(coalesce(PRODUCT_CATEGORY,msc.category)) as CATEGORY_PRE ,PRODUCT_SUB_CATEGORY ,sc.PRODUCT_TYPE ,upper(coalesce(sc.COLLECTION,msc.collection,mscc.collection)) as collection_pre ,sc.PRINT ,coalesce(sc.child_category_code, sc.category_code) as category_code ,SALEORDERITEMCODE ,ifnull((sc.BAU_MRP_ONLINE),0) as BAU_MRP_SALES ,(ifnull(SELLING_PRICE,0)) as SALES ,ifnull(case when tm.marketplace is not null then ( (case when ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0) >= (ifnull(SELLING_PRICE,0)) then ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0) - (ifnull(SELLING_PRICE,0)) else 0 end)) else 0 end,0) as bau_discount1 ,ifnull((ifnull(mc.commission_value,0) * ifnull(selling_price,0)),0) as muntr_sor ,ifnull(case when tm.marketplace is not null then ( (case when ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0) >= (ifnull(SELLING_PRICE,0)) then ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0) - (ifnull(SELLING_PRICE,0)) else 0 end)) else 0 end,0) + ( (ifnull((ifnull(ccogs.commission_value,0) * ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0)),0)) + ifnull((safe_divide(ifnull(ccogs.actual_value,0), count(*) over(partition by ccogs.start_date,ccogs.end_date,lower(ccogs.MARKETPLACE)))),0) ) as TRADE_MARGIN ,(ifnull((ifnull(ccogs.commission_value,0) * ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0)),0)) + ifnull((safe_divide(ifnull(ccogs.actual_value,0), count(*) over(partition by ccogs.start_date,ccogs.end_date,lower(ccogs.MARKETPLACE)))),0) as CCOGS ,case when tm.marketplace is null then ( (case when ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0) >= (ifnull(SELLING_PRICE,0)) then ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0) - (ifnull(SELLING_PRICE,0)) else 0 end)) else 0 end as BAU_DISCOUNT ,( 0.18 * ( IFNULL(SELLING_PRICE, 0) - IFNULL(RS.commission_value * IFNULL(SELLING_PRICE, 0), 0) ) ) / (1 + 0.18) AS GST ,(cm.commission_value * ifnull(selling_price,0)) as CHANNEL_MARGIN ,case when (ifnull(RS.commission_value,0) * ifnull(selling_price,0)) = 0 then safe_divide(RS.Actual_value,count(*)over(partition by last_day(coalesce(order_date,rs.start_date)),lower(coalesce(sc.marketplace,rs.marketplace)))) else (RS.commission_value * ifnull(selling_price,0)) end as RETURNS ,case when (ifnull(lc.commission_value,0) * (case when tm.marketplace is not null then ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0) else ifnull(selling_price,0) end)) = 0 then safe_divide(lc.Actual_value,count(*)over(partition by last_day(coalesce(order_date,lc.start_date)),lower(coalesce(sc.marketplace,lc.marketplace)))) else (lc.commission_value * (case when tm.marketplace is not null then ifnull(coalesce(sc.BAU_MRP_ONLINE,SELLING_PRICE),0) else ifnull(selling_price,0) end) ) end as LOGISTICS_COST ,ifnull(SC.quantity,0) as Quantity ,(cogs.cogs * ifnull(quantity,0)) - ifnull( case when cm.MARKETPLACE is not null then rs.commission_value * (cogs.cogs * ifnull(quantity,0)) end,0) as cogs ,(cogs.cogs * ifnull(quantity,0)) as initial_cogs ,IFNULL( store.daily_fixed_value * SAFE_DIVIDE(IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store.store)) )), store.daily_fixed_value ) + IFNULL(store.commission_percent * IFNULL(selling_price, 0), 0) AS exhibition_cost, IFNULL( store_rent.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store)) ) ), store_rent.daily_fixed_value ) + IFNULL(store_rent.commission_percent * IFNULL(selling_price, 0), 0) AS store_rent, IFNULL( store_cam.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE,store_rent.store, store_cam.store)) ) ), store_cam.daily_fixed_value ) + IFNULL(store_cam.commission_percent * IFNULL(selling_price, 0), 0) AS store_cam, IFNULL( store_elec.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store)) ) ), store_elec.daily_fixed_value ) + IFNULL(store_elec.commission_percent * IFNULL(selling_price, 0), 0) AS store_elec, IFNULL( store_int.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store)) ) ), store_int.daily_fixed_value ) + IFNULL(store_int.commission_percent * IFNULL(selling_price, 0), 0) AS store_int, IFNULL( store_hvac.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store)) ) ), store_hvac.daily_fixed_value ) + IFNULL(store_hvac.commission_percent * IFNULL(selling_price, 0), 0) AS store_hvac, IFNULL( store_other.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store,store_other.store)) ) ), store_other.daily_fixed_value ) + IFNULL(store_other.commission_percent * IFNULL(selling_price, 0), 0) AS store_other, IFNULL( store_salary.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store,store_other.store, store_salary.store)) ) ), store_salary.daily_fixed_value ) + IFNULL(store_salary.commission_percent * IFNULL(selling_price, 0), 0) AS store_salary, IFNULL( store_incentive.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store, store_other.store, store_salary.store, store_incentive.store)) ) ), 0 ) + IFNULL(store_incentive.commission_percent * IFNULL(selling_price, 0), 0) AS store_incentive, IFNULL( store_bank.daily_fixed_value * SAFE_DIVIDE( IFNULL(selling_price, 0), SUM(IFNULL(selling_price, 0)) OVER ( PARTITION BY CAST(COALESCE(ORDER_DATE, marketing_nocategory_date, marketing_date) AS DATE), LOWER(COALESCE(SOURCE, store_rent.store, store_cam.store, store_elec.store, store_int.store, store_hvac.store, store_other.store, store_salary.store, store_bank.store)) ) ), 0 ) + IFNULL(store_bank.commission_percent * IFNULL(selling_price, 0), 0) AS store_bank, store_revenue.commission_percent as store_revenue_Share from ( select sc.* ,coalesce((ifnull(SELLING_PRICE,0)) / (1-tm.commission_value) ,GREATEST(ifnull(BAU_ONLINE,0),ifnull(SELLING_PRICE,0))) as BAU_MRP_ONLINE from MapleMonk.zouk_sales_consolidated_temp sc left join ( select PARSE_DATE(\'%d-%b-%y\',START_DATE) START_DATE ,PARSE_DATE(\'%d-%b-%y\',END_DATE) END_DATE ,MARKETPLACE ,cast(replace(ifnull(commission_value,\'0\'),\'%\',\'\') as float64)/100 as commission_value ,cast(Actual_Value as float64) as Actual_Value from MapleMonk.STPL_Marketplace_Commissions where upper(PANDL_CATEGORY) = \'TRADE MARGIN\' qualify row_number() over(partition by START_DATE,END_DATE,lower(marketplace) order by 1) = 1 ) tm on cast(ORDER_DATE as date) >= cast(tm.START_DATE as date) and cast(ORDER_DATE as date) <= cast(tm.END_DATE as date) and lower(sc.marketplace) = lower(tm.MARKETPLACE) where not(lower(ifnull(ORDER_STATUS,\'\')) like \'%cancel%\' or lower(ifnull(FINAL_SHIPPING_STATUS,\'\')) like \'%cancel%\') and lower(brand) like any (\'%everpret%\',\'%doto%\') ) SC left join ( select distinct upper(MARKETPLACE) MARKETPLACE from MapleMonk.STPL_Marketplace_Commissions where upper(PANDL_CATEGORY) = \'TRADE MARGIN\' ) tm on lower(sc.marketplace) = lower(tm.MARKETPLACE) left join ( select PARSE_DATE(\'%d-%b-%y\',START_DATE) START_DATE ,PARSE_DATE(\'%d-%b-%y\',END_DATE) END_DATE ,MARKETPLACE ,case when lower(Commission_Type) like \'%percent%\' then cast(replace(commission_value,\'%\',\'\') as float64)/100 end as commission_value ,case when lower(Commission_Type) not like \'%percent%\' and current_date() > PARSE_DATE(\'%d-%b-%y\',END_DATE) then cast(replace(commission_value,\',\',\'\') as float64) else (cast(replace(commission_Value,\'%\',\'\') as float64)/cast(EXTRACT(DAY FROM PARSE_DATE(\'%d-%b-%y\',END_DATE)) as int64))* cast(EXTRACT (DAY FROM current_date()) as int64) end as actual_value from MapleMonk.c_cogs where upper(PANDL_CATEGORY) = \'C COGS\' )ccogs on cast(ORDER_DATE as date) >= cast(ccogs.START_DATE as date) and cast(ORDER_DATE as date) <= cast(ccogs.END_DATE as date) and lower(sc.marketplace) = lower(ccogs.MARKETPLACE) left join ( select PARSE_DATE(\'%d-%b-%y\',START_DATE) START_DATE ,PARSE_DATE(\'%d-%b-%y\',END_DATE) END_DATE ,MARKETPLACE ,cast(replace(ifnull(commission_value,\'0\'),\'%\',\'\') as float64)/100 as commission_value ,cast(Actual_Value as float64) as Actual_Value from MapleMonk.STPL_Marketplace_Commissions where upper(PANDL_CATEGORY) = \'TRADE MARGIN\' and lower(marketplace) like \'%myntra_sor%\' )mc on cast(ORDER_DATE as date) >= cast(mc.START_DATE as date) and cast(ORDER_DATE as date) <= cast(mc.END_DATE as date) and lower(sc.marketplace) = lower(mc.MARKETPLACE) left join (Select * from ( select *,row_number() over(partition by lower(ifnull(commonsku,\'\')) order by 1)rw from maplemonk.final_sku_master )where rw = 1 ) fsm on lower(fsm.commonsku) = lower(ifnull(sc.commonsku,\'\')) left join ( select PARSE_DATE(\'%d-%b-%y\',START_DATE) START_DATE ,PARSE_DATE(\'%d-%b-%y\',END_DATE) END_DATE ,MARKETPLACE ,PANDL_CATEGORY ,cast(replace(commission_value,\'%\',\'\') as float64)/100 as commission_value ,cast(Actual_Value as float64) as Actual_Value from(select *,row_number() over(partition by START_DATE,END_DATE,lower(MARKETPLACE) order by 1)rw from MapleMonk.STPL_Marketplace_Commissions) where upper(PANDL_CATEGORY) = \'CHANNEL MARGIN\' and rw =1 )cm on cast(ORDER_DATE as date) >= cast(cm.START_DATE as date) and cast(ORDER_DATE as date) <= cast(cm.END_DATE as date) and lower(sc.marketplace) = lower(cm.MARKETPLACE) left join ( select PARSE_DATE(\'%d-%b-%y\',START_DATE) START_DATE ,PARSE_DATE(\'%d-%b-%y\',END_DATE) END_DATE ,MARKETPLACE ,cast(replace(Estimated_Return_Share,\'%\',\'\') as float64)/100 as commission_value ,cast(Actual_Return_Value as float64) as Actual_Value from MapleMonk.STPL_returns_share )rs on cast(ORDER_DATE as date) >= cast(rs.START_DATE as date) and cast(ORDER_DATE as date) <= cast(rs.END_DATE as date) and lower(sc.marketplace) = lower(rs.MARKETPLACE) left join ( select PARSE_DATE(\'%d-%b-%y\',START_DATE) START_DATE ,PARSE_DATE(\'%d-%b-%y\',END_DATE) END_DATE ,category_code ,cast(replace(cogs,\',\',\'\') as float64) as cogs from `MapleMonk.zouk_db_SKU_MRP_COGS` qualify row_number() over(partition by START_DATE,END_DATE,lower(category_code) order by 1) = 1 )cogs on cast(sc.ORDER_DATE as date) >= cast(cogs.START_DATE as date) and cast(sc.ORDER_DATE as date) <= cast(cogs.END_DATE as date) and lower(coalesce(sc.child_category_code, sc.category_code)) = lower(cogs.category_code) Full Outer join ( select cast(null as date) as marketing_date ,cast(null as string) as marketing_channel ,cast(null as string) category ,cast(null as string) collection ,0 as spend ,0 as Brand_Spend from maplemonk.STPL_MARKETING_CONSOLIDATED_temp limit 0 )msc on cast(msc.marketing_date as date) = cast(sc.order_Date as date) and lower(msc.marketing_channel) = lower(sc.channel) and lower(sc.PRODUCT_CATEGORY) = lower(msc.category) Full Outer join ( select cast(null as date) as marketing_nocategory_date ,cast(null as string) as marketing_nocategory_channel ,cast(null as string) collection ,0 as spend ,0 as Brand_Spend from mapl